func:
// TASK SETTINGS: the settings of this flow only (dry run per table).
// In: any message from an inject node. Out: the same message.
// It copies the shared settings from global context into flow context and
// builds the file path of every table.
var DRY_RUN = {
  pbi_machine_names: true,
  pbi_shift_naming: true,
  pbi_calendar: true
};
// First and last date of the calendar table.
var CALENDAR_START = '2026-09-01';
var CALENDAR_END = '2026-12-31';

var shared = glob.get('cfg');
if (!shared) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'CONFIG not run'
  });
  node.error('global cfg is missing: deploy or run the Config tab first');
  return null;
}

var cfg = Object.assign({}, shared);
cfg.dryRun = DRY_RUN;
cfg.calendarStart = CALENDAR_START;
cfg.calendarEnd = CALENDAR_END;
cfg.paths = {};
Object.keys(DRY_RUN).forEach(function (table) {
  cfg.paths[table] = shared.root + '/' + table + '/' + table + '.parquet';
});
cfg.assetIds = [];
shared.sites.forEach(function (site) {
  cfg.assetIds = cfg.assetIds.concat(site.assetIds);
});
flow.set('cfg', cfg);

var writing = Object.keys(DRY_RUN).filter(function (table) {
  return !DRY_RUN[table];
});
node.status({
  fill: writing.length ? 'green' : 'yellow',
  shape: 'dot',
  text: writing.length ? writing.length + ' table(s) WRITE' : 'DRY RUN'
});
return msg;

// Starts one run. In: any message from CONFIG (inject or test start).
// Out: msg.payload = the run day text YYYY-MM-DD, and msg.mode.
// A start like {start: 'YYYY-MM-DD'} fixes the day, otherwise it is today.
var day = new Date().toISOString().slice(0, 10);
var start = msg.payload;
if (start && typeof start === 'object' && start.start) {
  day = start.start;
}
msg.payload = day;
msg.mode = 'reference';
return msg;

// Builds the pbi_calendar table: one row per date, Monday week start.
// In: any message after the settings node. Out 1: msg.payload = the rows
// (topic pbi_calendar). Out 2: a log line. Dry run sends only the log line.
var DAY_MS = 86400000;
var cfg = flow.get('cfg');
var MONTHS = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December'
];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}

// ISO week number (Monday start, week 1 holds the first Thursday).
function isoWeek(ms) {
  var d = new Date(ms);
  d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
  var yearStart = Date.UTC(d.getUTCFullYear(), 0, 1);
  return Math.ceil(((d.getTime() - yearStart) / DAY_MS + 1) / 7);
}

var rows = [];
var start = Date.parse(cfg.calendarStart + 'T00:00:00Z');
var end = Date.parse(cfg.calendarEnd + 'T00:00:00Z');
for (var t = start; t <= end; t += DAY_MS) {
  var d = new Date(t);
  var month = d.getUTCMonth();
  var year = d.getUTCFullYear();
  var quarter = Math.floor(month / 3) + 1;
  var mondayOffset = (d.getUTCDay() + 6) % 7;
  rows.push({
    date: d.toISOString().slice(0, 10),
    year: year,
    month_number: month + 1,
    month: MONTHS[month],
    month_short_name: MONTHS[month].slice(0, 3),
    month_year: MONTHS[month].slice(0, 3) + ' ' + year,
    month_year_number: pad(month + 1) + ' ' + String(year).slice(2),
    quarter: 'QTR' + quarter,
    quarter_number: quarter,
    week_number: isoWeek(t),
    week_start: new Date(t - mondayOffset * DAY_MS).toISOString().slice(0, 10)
  });
}

var text = 'pbi_calendar ' + rows.length + ' rows';
if (cfg.dryRun.pbi_calendar) {
  var line = {
    topic: 'log',
    payload: 'calendar [setup] DRY RUN: ' + text
  };
  return [null, line];
}
var table = {
  topic: 'pbi_calendar',
  day: '',
  payload: rows
};
return [table, null];

// Builds the token request. The next node is an http request node.
// In: a day message {payload: 'YYYY-MM-DD', mode}.
// Out: msg.method, msg.url and msg.headers for the token POST.
var cfg = flow.get('cfg');
var credentials = cfg.clientId + ':' + cfg.clientSecret;
msg.day = msg.payload;
msg.loadedAt = Date.now();
msg.method = 'POST';
msg.url = 'https://' + cfg.tenantName +
  '.piam.eu1.mindsphere.io/oauth/token?grant_type=client_credentials';
msg.headers = {
  'Authorization': 'Basic ' + Buffer.from(credentials).toString('base64'),
  'Accept': 'application/json'
};
delete msg.payload;
return msg;

// Keeps the token and builds the OEE asset list request (isConfigured,
// isManual). In: the token response. Out 1: the request for the http node.
// Out 2: a log message when the token request failed.
var cfg = flow.get('cfg');
var token = msg.payload && msg.payload.access_token;

function logMessage(text) {
  return {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
}

if (msg.statusCode !== 200 || !token) {
  var failed = 'FAILED, NOTHING WRITTEN: token request failed, HTTP ';
  return [null, logMessage(failed + msg.statusCode)];
}
msg.token = token;
msg.method = 'GET';
msg.url = cfg.gateway + '/api/oee/v3/assets';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return [msg, null];

// Chooses the assets to read for the reference tables.
// In: the OEE asset list. Out 1: msg.payload = [{id, name, isManual,
// isConfigured, reasonTreeId}] for the split node. Out 2: a log message.
var cfg = flow.get('cfg');
var byId = {};
var skipped = [];
var targets = [];

function logMessage(text) {
  return {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
}

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
  var failed = 'FAILED, NOTHING WRITTEN: OEE asset list failed, HTTP ';
  return [null, logMessage(failed + msg.statusCode)];
}

msg.payload.forEach(function (o) {
  byId[o.assetId] = o;
});
var ids = cfg.assetIds;
if (!ids || !ids.length) {
  ids = msg.payload.map(function (o) {
    return o.assetId;
  });
}
ids.forEach(function (id) {
  var o = byId[id];
  if (!o) {
    skipped.push(String(id).slice(0, 6) + '... not an OEE asset');
    return;
  }
  if (cfg.excludeNames.indexOf(o.name) >= 0) {
    skipped.push(o.name + ' excluded');
    return;
  }
  targets.push({
    id: id,
    name: o.name,
    isManual: o.isManual,
    isConfigured: o.isConfigured !== false,
    reasonTreeId: o.reasonTreeId || null
  });
});
msg.planSkipped = skipped;

if (!targets.length) {
  var nothing = 'NOTHING TO WRITE (no assets to read)';
  if (skipped.length) {
    nothing += ' | skipped: ' + skipped.join('; ');
  }
  return [null, logMessage(nothing)];
}
msg.payload = targets;
node.status({
  fill: 'blue',
  shape: 'dot',
  text: targets.length + ' asset(s)'
});
return [msg, null];

// Builds the Asset Management request for one asset (to get hierarchyPath).
// In: one asset {id, isManual, name} from the split node.
// Out: msg.method, msg.url and msg.headers for the http request node.
var cfg = flow.get('cfg');
msg.asset = msg.payload;
msg.method = 'GET';
msg.url = cfg.gateway + '/api/assetmanagement/v3/assets/' +
  encodeURIComponent(msg.asset.id);
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/hal+json'
};
delete msg.payload;
return msg;

// Saves the hierarchy of one asset and builds the OEE config request.
// In: the Asset Management response. Out 1: the config request.
// Out 2: the message for stage 3.4 when no config call is needed
// (details failed, asset excluded or asset not configured).
var cfg = flow.get('cfg');

// Names are root first. Tenant layout: [0] tenant, [1] region, [2] site,
// [3] area, [4] line, [5] machine. GT4 has no machine, so it is the line.
function hierarchyFromNames(names) {
  return {
    asset_name: names[names.length - 1] || null,
    site: names[2] || null,
    area: names[3] || null,
    line: names[4] || null,
    machine: names[5] || null
  };
}

var details = msg.payload;
msg.amFail = null;
msg.skip = null;
msg.h = null;
if (msg.statusCode !== 200 || !details || !details.name) {
  var text = msg.asset.name + ': asset details failed, HTTP ';
  msg.amFail = text + msg.statusCode;
} else {
  var names = (details.hierarchyPath || []).map(function (p) {
    return p.name;
  });
  names.push(details.name);
  msg.h = hierarchyFromNames(names);
  var excluded = cfg.excludeNames.indexOf(details.name) >= 0;
  var parentExcluded = names.slice(0, -1).some(function (n) {
    return cfg.excludeAncestorNames.indexOf(n) >= 0;
  });
  if (excluded || parentExcluded) {
    msg.skip = 'excluded';
  } else if (!msg.asset.isConfigured) {
    msg.skip = 'not configured';
  }
}

if (msg.amFail || msg.skip) {
  delete msg.payload;
  return [null, msg];
}
msg.method = 'GET';
msg.url = cfg.gateway + '/api/oee/v3/assets/' +
  encodeURIComponent(msg.asset.id) + '/config';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return [msg, null];

// Builds the two items of one asset: its machine name row and its calendar.
// In: msg.asset, msg.h, msg.amFail, msg.skip, the OEE config response.
// Out: msg.payload = {machine, calendar}. machine = {name, failed, skipped,
// rows}. calendar = {name, value (the calendar id), failed, skipped}.
var asset = msg.asset;
var config = msg.payload || {};
var machine = {
  name: asset.name,
  failed: null,
  skipped: null,
  rows: []
};
var calendar = {
  name: asset.name,
  value: null,
  failed: null,
  skipped: null
};

if (msg.amFail) {
  machine.failed = msg.amFail;
  calendar.failed = msg.amFail;
} else if (msg.skip === 'excluded') {
  machine.skipped = asset.name + ' excluded';
  calendar.skipped = asset.name + ' excluded';
} else {
  machine.rows.push({
    site_name: msg.h.site,
    area: msg.h.area,
    dept: msg.h.area,
    machine_name: msg.h.asset_name,
    product_type: null,
    unique_machine_name: asset.id,
    loaded_at: msg.loadedAt
  });
  if (msg.skip === 'not configured') {
    calendar.skipped = asset.name + ' not configured';
  } else if (msg.statusCode !== 200) {
    calendar.failed = asset.name + ': config failed, HTTP ' + msg.statusCode;
  } else {
    calendar.value = config.calendarId || null;
  }
}

msg.payload = {
  machine: machine,
  calendar: calendar
};
return msg;

// Splits the asset bundles into one message per table.
// In: msg.payload = array of {machine, calendar}.
// Out 1: the machine items. Out 2: the calendar items (for the shift names).
var KEYS = [
  'machine',
  'calendar'
];
var bundles = msg.payload;

function messageFor(key) {
  var copy = Object.assign({}, msg);
  copy.payload = bundles.map(function (bundle) {
    return bundle[key];
  });
  return copy;
}

node.status({
  fill: 'blue',
  shape: 'dot',
  text: bundles.length + ' asset(s)'
});
return KEYS.map(messageFor);

// Collects the items that the join delivered into one list of rows.
// In: msg.payload = array of items {name, failed, skipped, rows}.
// Out: msg.rows, msg.failed and msg.skipped (lists), msg.itemCount.
var items = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
var rows = [];
var failed = [];
var skipped = (msg.planSkipped || []).slice();

items.forEach(function (item) {
  if (!item) {
    return;
  }
  if (item.failed) {
    failed.push(item.failed);
  }
  if (item.skipped) {
    skipped.push(item.skipped);
  }
  rows = rows.concat(item.rows || []);
});
msg.rows = rows;
msg.failed = failed;
msg.skipped = skipped;
msg.itemCount = items.length;
delete msg.payload;
return msg;

// Decides what happens with the table pbi_machine_names.
// In: msg.rows, msg.failed, msg.skipped. Out 1: msg.payload = rows for the
// parquet node. Out 2: a log line. A failed item means nothing is written.
var TABLE = 'pbi_machine_names';
var cfg = flow.get('cfg');
var rows = msg.rows;
var tail = '';
if (msg.skipped.length) {
  tail += ' | skipped: ' + msg.skipped.join('; ');
}
var sizes = TABLE + ' ' + rows.length + ' rows from ' +
  msg.itemCount + ' item(s)';

function logOnly(text) {
  var line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
  return [null, line];
}

if (msg.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + msg.failed.join(' | ') + tail
  );
}
if (!rows.length) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'nothing to write'
  });
  return logOnly('NOTHING TO WRITE: ' + sizes + tail);
}
if (cfg.dryRun[TABLE]) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: 'dry run ' + rows.length
  });
  var firstRows = JSON.stringify(rows.slice(0, 2));
  return logOnly('DRY RUN: ' + sizes + '. First rows: ' + firstRows + tail);
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: 'writing ' + rows.length
});
var writing = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] WRITING ' + sizes + tail
};
msg.payload = rows;
delete msg.rows;
return [msg, writing];

// Sets the file path in the data lake.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The file name is
// fixed, so every run replaces the file and never duplicates it.
var cfg = flow.get('cfg');
msg.path = cfg.paths['pbi_machine_names'];
msg.filename = msg.path.split('/').pop();
return msg;

// Collects the distinct ids of the assets.
// In: msg.payload = array of items {name, value, failed, skipped}.
// Out 1: msg.ids (list of ids). Out 2: a log line when an item failed or
// there is no id at all.
var seen = {};
var ids = [];
var failures = [];
var without = [];

function logMessage(text) {
  return {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
}

msg.payload.forEach(function (item) {
  if (item.failed) {
    failures.push(item.failed);
    return;
  }
  if (item.skipped) {
    return;
  }
  var id = item.value;
  if (!id) {
    without.push(item.name);
    return;
  }
  if (!seen[id]) {
    seen[id] = true;
    ids.push(id);
  }
});

if (failures.length) {
  var failed = 'FAILED, NOTHING WRITTEN: ' + failures.join(' | ');
  return [null, logMessage(failed)];
}
if (!ids.length) {
  var nothing = 'NOTHING TO WRITE (no ids found)';
  if (without.length) {
    nothing += ' | assets without id: ' + without.join(', ');
  }
  return [null, logMessage(nothing)];
}
if (without.length) {
  var note = ' | assets without id: ' + without.join(', ');
  msg.planSkipped = (msg.planSkipped || []).concat(note);
}
msg.ids = ids;
delete msg.payload;
return [msg, null];

// Turns the distinct calendar ids into one target per id.
// In: msg.ids (list of calendar ids). Out: msg.payload = [{id, name, extra}]
// for the split node.
msg.payload = msg.ids.map(function (id) {
  return {
    id: id,
    name: null,
    extra: null
  };
});
delete msg.ids;
node.status({
  fill: 'blue',
  shape: 'dot',
  text: msg.payload.length + ' calendar(s)'
});
return msg;

// Builds the GET request for one id (reason tree, collection or calendar).
// In: one target {id, name, extra} from the split node.
// Out: msg.method, msg.url and msg.headers for the http request node.
var PATH_BEFORE = 'calendars/';
var PATH_AFTER = '/calendarEvents';
var WITH_WINDOW = true;
var DAY_MS = 86400000;
var cfg = flow.get('cfg');
msg.target = msg.payload;
var url = cfg.gateway + '/api/oee/v3/' + PATH_BEFORE +
  encodeURIComponent(msg.target.id) + PATH_AFTER;

// Calendar events are read for a window that starts on the run day.
if (WITH_WINDOW) {
  var from = Date.parse(msg.day + 'T00:00:00.000Z');
  var to = from + cfg.calendarWindowDays * DAY_MS;
  url += '?from=' + new Date(from).toISOString();
  url += '&to=' + new Date(to).toISOString();
}
msg.method = 'GET';
msg.url = url;
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return msg;

// Builds the shift name rows of one calendar: one row per event name.
// In: the calendarEvents response and msg.target (the calendar id).
// Out: msg.payload = an item {name, failed, skipped, rows} for the join.
var target = msg.target;
var label = 'calendar ' + String(target.id).slice(0, 6) + '...';
var item = {
  name: label,
  failed: null,
  skipped: null,
  rows: []
};

var events = msg.payload && msg.payload.calendarEvents;
if (msg.statusCode !== 200 || !Array.isArray(events)) {
  item.failed = label + ' failed, HTTP ' + msg.statusCode;
  msg.payload = item;
  return msg;
}

events.forEach(function (e) {
  if (e.name) {
    item.rows.push({
      shift: e.name,
      loaded_at: msg.loadedAt
    });
  }
});
msg.payload = item;
return msg;

// Collects the items that the join delivered into one list of rows.
// In: msg.payload = array of items {name, failed, skipped, rows}.
// Out: msg.rows, msg.failed and msg.skipped (lists), msg.itemCount.
var items = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
var rows = [];
var failed = [];
var skipped = (msg.planSkipped || []).slice();

items.forEach(function (item) {
  if (!item) {
    return;
  }
  if (item.failed) {
    failed.push(item.failed);
  }
  if (item.skipped) {
    skipped.push(item.skipped);
  }
  rows = rows.concat(item.rows || []);
});
msg.rows = rows;
msg.failed = failed;
msg.skipped = skipped;
msg.itemCount = items.length;
delete msg.payload;
return msg;

// Keeps every shift name once.
// In: msg.rows = the shift rows of all calendars (names repeat).
// Out: msg.rows = the distinct shift names, in the order first seen.
var seen = {};
msg.rows = msg.rows.filter(function (row) {
  if (seen[row.shift]) {
    return false;
  }
  seen[row.shift] = true;
  return true;
});
return msg;

// Decides what happens with the table pbi_shift_naming.
// In: msg.rows, msg.failed, msg.skipped. Out 1: msg.payload = rows for the
// parquet node. Out 2: a log line. A failed item means nothing is written.
var TABLE = 'pbi_shift_naming';
var cfg = flow.get('cfg');
var rows = msg.rows;
var tail = '';
if (msg.skipped.length) {
  tail += ' | skipped: ' + msg.skipped.join('; ');
}
var sizes = TABLE + ' ' + rows.length + ' rows from ' +
  msg.itemCount + ' item(s)';

function logOnly(text) {
  var line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
  return [null, line];
}

if (msg.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + msg.failed.join(' | ') + tail
  );
}
if (!rows.length) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'nothing to write'
  });
  return logOnly('NOTHING TO WRITE: ' + sizes + tail);
}
if (cfg.dryRun[TABLE]) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: 'dry run ' + rows.length
  });
  var firstRows = JSON.stringify(rows.slice(0, 2));
  return logOnly('DRY RUN: ' + sizes + '. First rows: ' + firstRows + tail);
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: 'writing ' + rows.length
});
var writing = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] WRITING ' + sizes + tail
};
msg.payload = rows;
delete msg.rows;
return [msg, writing];

// Sets the file path in the data lake.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The file name is
// fixed, so every run replaces the file and never duplicates it.
var cfg = flow.get('cfg');
msg.path = cfg.paths['pbi_shift_naming'];
msg.filename = msg.path.split('/').pop();
return msg;

// Sets the file path in the data lake.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The file name is
// fixed, so every run replaces the file and never duplicates it.
var cfg = flow.get('cfg');
msg.path = cfg.paths['pbi_calendar'];
msg.filename = msg.path.split('/').pop();
return msg;

// Turns an error caught by the catch node into a log line.
// In: the message of a catch node (msg.error).
// Out: a log line for the shared log. Errors of the log nodes themselves
// are dropped (no log loop).
var err = msg.error || {};
var source = (err.source && err.source.name) || 'unknown node';

function textOf(value) {
  if (value === undefined || value === null) {
    return '';
  }
  if (typeof value === 'string') {
    return value;
  }
  return JSON.stringify(value);
}

// Takes the API message out of an error body when there is one.
function apiMessage(value) {
  var body = value;
  if (typeof value === 'string') {
    try {
      body = JSON.parse(value);
    } catch (e) {
      return value;
    }
  }
  var data = body && body.data;
  var list = (data && data.errors) || (body && body.errors);
  if (list && list.length && list[0].message) {
    return list[0].message;
  }
  return textOf(value);
}

if (msg.logBatch) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'log write failed'
  });
  return null;
}

var text = '';
if (msg.day) {
  text += msg.day + ' [' + msg.mode + '] ';
}
text += 'ERROR in ' + source + ': ' + apiMessage(err.message);
return {
  topic: 'log',
  payload: text,
  level: 'error',
  source: source
};

// Turns one log message into a row for the log file.
// In: msg.payload = log text (optional msg.level and msg.source).
// Out: msg.payload = the row, msg.line = the text for the debug node.
var FLOW_NAME = 'pbi-reference';
var cfg = flow.get('cfg') || {};
var text = String(msg.payload);

var seq = (flow.get('logSeq') || 0) + 1;
flow.set('logSeq', seq);

// Most lines start with the production day and the mode: "2026-09-01 [x] ".
var day = '';
var mode = '';
var message = text;
var parts = /^(\d{4}-\d{2}-\d{2}) \[([^\]]*)\] ([\s\S]*)$/.exec(text);
if (parts) {
  day = parts[1];
  mode = parts[2];
  message = parts[3];
}

var level = msg.level;
if (!level) {
  if (/FAILED/.test(message)) {
    level = 'failed';
  } else if (/NOTHING TO WRITE/.test(message)) {
    level = 'warn';
  } else {
    level = 'info';
  }
}

msg.line = text;
msg.payload = {
  ts_utc: new Date().toISOString(),
  seq: seq,
  flow: FLOW_NAME,
  site: cfg.site || 'all',
  production_day: day,
  mode: mode,
  level: level,
  source: msg.source || 'flow',
  message: message
};
return msg;

// Prepares the write of one batch of log rows (the read node runs next).
// In: msg.payload = array of log rows from the join node.
// Out: msg.path = file of the month, msg.logRows, msg.logBatchId, no payload.
// msg.logBatch keeps errors of the log nodes themselves out of the log.
var FLOW_NAME = 'pbi-reference';
var cfg = flow.get('cfg') || {};
var root = cfg.root || 'logs_without_root';
var rows = msg.payload;
var month = rows[0].ts_utc.slice(0, 7);

var batchNo = (flow.get('logBatchNo') || 0) + 1;
flow.set('logBatchNo', batchNo);

msg.logRows = rows;
msg.path = root + '/logs/' + FLOW_NAME + '/log_' + month + '.csv';
msg.logBatch = true;
msg.logBatchId = rows[0].ts_utc + '#' + batchNo;
delete msg.payload;
return msg;

// Adds the rows of one batch to the log file of the month.
// In: msg.payload = the old file (read answered) or nothing (no answer).
// Out: msg.payload = the whole new file, the data lake has no append.
// The same batch can arrive twice (read answer, then the wait): once only.
var SEPARATOR = ',';
var KEEP_IDS = 50;
var COLUMNS = [
  'ts_utc',
  'seq',
  'flow',
  'site',
  'production_day',
  'mode',
  'level',
  'source',
  'message'
];

// Quotes inside a field are doubled, line breaks become a space.
function quote(value) {
  var text = (value === undefined || value === null) ? '' : String(value);
  text = text.replace(/"/g, '""').replace(/[\r\n]+/g, ' ');
  return '"' + text + '"';
}

function lineOf(row) {
  return COLUMNS.map(function (name) {
    return quote(row[name]);
  }).join(SEPARATOR);
}

// The read node gives text, or a serialised buffer.
function decode(payload) {
  if (typeof payload === 'string') {
    return payload;
  }
  if (payload && payload.type === 'Buffer' && payload.data) {
    var bin = '';
    payload.data.forEach(function (byte) {
      bin += String.fromCharCode(byte);
    });
    try {
      return decodeURIComponent(escape(bin));
    } catch (e) {
      return bin;
    }
  }
  return null;
}

var rows = msg.logRows.slice();
rows.sort(function (a, b) {
  if (a.ts_utc !== b.ts_utc) {
    return a.ts_utc < b.ts_utc ? -1 : 1;
  }
  return a.seq - b.seq;
});

var done = flow.get('logDone') || [];
var known = flow.get('logKnown') || [];
if (done.indexOf(msg.logBatchId) >= 0) {
  return null;
}

var path = msg.path;
var old = '';
var problem = '';
if (msg.payload === undefined || msg.payload === null) {
  if (known.indexOf(path) >= 0) {
    problem = 'read gave no answer for a file written before';
  }
} else {
  old = decode(msg.payload);
  if (old === null) {
    old = '';
    problem = 'old file is not text';
  }
}
if (problem) {
  // Never replace the old file: write a new one with a time stamp.
  var stamp = new Date().toISOString().replace(/[-:.TZ]/g, '');
  path = path.replace(/\.csv$/, '_' + stamp + '.csv');
  rows.push({
    ts_utc: new Date().toISOString(),
    seq: 0,
    flow: rows[0].flow,
    site: rows[0].site,
    production_day: '',
    mode: '',
    level: 'error',
    source: 'log',
    message: problem + ', wrote ' + path
  });
} else if (known.indexOf(path) < 0) {
  known.push(path);
  flow.set('logKnown', known);
}

var lines = [];
if (!old) {
  lines.push(COLUMNS.map(quote).join(SEPARATOR));
} else if (old.slice(-1) !== '\n') {
  old += '\n';
}
rows.forEach(function (row) {
  lines.push(lineOf(row));
});

done.push(msg.logBatchId);
flow.set('logDone', done.slice(-KEEP_IDS));

msg.payload = old + lines.join('\n') + '\n';
msg.path = path;
delete msg.logRows;
return msg;
